"use client";

import Image from "next/image";
import { motion, useReducedMotion, useScroll, useTransform } from "framer-motion";
import { useRef } from "react";

/** Scroll distance (× viewport height) driving the hero background animation */
const SCROLL_FACTOR = 1.85;

export default function Hero() {
  const scrollRef = useRef<HTMLDivElement>(null);
  const prefersReducedMotion = useReducedMotion() === true;

  const { scrollYProgress } = useScroll({
    target: scrollRef,
    offset: ["start start", "end start"],
  });

  const scale = useTransform(
    scrollYProgress,
    [0, 1],
    prefersReducedMotion ? [1, 1] : [1, 1.18],
  );
  const imageOpacity = useTransform(
    scrollYProgress,
    [0, 1],
    prefersReducedMotion ? [1, 1] : [1, 0],
  );

  return (
    <div
      ref={scrollRef}
      className="relative w-full max-w-[100vw]"
      style={{ height: `${SCROLL_FACTOR * 100}svh` }}
    >
      <section className="sticky top-0 flex h-[100svh] min-h-[100dvh] w-full max-w-[100vw] flex-col overflow-hidden bg-black">
        <div className="absolute inset-0 z-0 bg-black" />

        <motion.div
          className="absolute inset-0 z-[1] will-change-transform"
          style={{ scale, opacity: imageOpacity }}
        >
          <Image
            src="/placeholder_image.jpg"
            alt="Hero background (placeholder)"
            fill
            priority
            sizes="(max-width: 768px) 100vw, (max-width: 1024px) 100vw, 100vw"
            className="object-cover object-center"
          />
        </motion.div>

        <div className="relative z-10 flex min-h-full max-w-[100vw] flex-col justify-end pb-[max(2rem,calc(env(safe-area-inset-bottom,0px)+8vh))] pl-[max(1rem,env(safe-area-inset-left,0px)+5vw)] pr-[max(1rem,env(safe-area-inset-right,0px))] md:pl-[max(2.5rem,env(safe-area-inset-left,0px)+10vh)]">
          <h1 className="flex w-full max-w-full flex-col gap-0 text-balance break-words text-[#ffffff]">
            <span className="block max-w-full font-garamond text-[clamp(2.625rem,calc(0.65rem+10.5vmin),11.25rem)] font-normal italic leading-[0.92]">
              {`Hi, I'm`}
            </span>
            <span className="-mt-[0.06em] block max-w-full font-garamond text-[clamp(2.625rem,calc(0.65rem+10.5vmin),11.25rem)] font-bold not-italic leading-[0.92]">
              Amogh
            </span>
          </h1>
        </div>
      </section>
    </div>
  );
}
